class DiscountStrategy {

    /*
    This is a class that allows to use different discount strategy based on shopping credit or shopping cart in supermarket.
    */

    let customer: Customer
    let cart: ArrayList<Product>
    let promotion: (DiscountStrategy) -> Float64

    public init(customer: Customer, cart: ArrayList<Product>, promotion!: (DiscountStrategy) -> Float64 = {_ => 0.0}) {
        /*
        Initialize the DiscountStrategy with customer information, a cart of items, and an optional promotion.
        :param customer: Customer, customer information
        :param cart: list of Product, a cart of items with details
        :param promotion: function, optional promotion applied to the order
        >>> customer = Customer('John Doe', 1200)
        >>> cart = ArrayList<Product>()
        >>> cart.add(Product('product', 14, 23.5))
        >>> DiscountStrategy(customer, cart, promotion: DiscountStrategy.FidelityPromo)

        */
        this.customer = customer
        this.cart = cart
        this.promotion = promotion
    }

    public func total(): Float64 {
        /*
        Calculate the total cost of items in the cart.
        :return: Float64, total cost of items
        >>> customer = Customer('John Doe', 1200)
        >>> cart = ArrayList<Product>()
        >>> cart.add(Product('product', 14, 23.5))
        >>> ds = DiscountStrategy(customer, cart)
        >>> ds.total()
        329.0

        */
        var sum: Float64 = 0.0
        for (i in 0..cart.size) {
            let item = cart[i]
            sum = sum + item.quantity * item.price
        }
        sum
    }

    public func due(): Float64 {
        /*
        Calculate the final amount to be paid after applying the discount.
        :return: Float64, final amount to be paid
        >>> customer = Customer('John Doe', 1200)
        >>> cart = ArrayList<Product>()
        >>> cart.add(Product('product', 14, 23.5))
        >>> ds = DiscountStrategy(customer, cart, promotion: DiscountStrategy.FidelityPromo)
        >>> ds.due()
        312.55

        */
        let t = this.total()
        let discount = this.promotion(this)
        t - discount
    }

    public static func FidelityPromo(order: DiscountStrategy): Float64 {
        /*
        Calculate the discount based on the fidelity points of the customer.Customers with over 1000 points can enjoy a 5% discount on the entire order.
        :param order: DiscountStrategy, the order to apply the discount to
        :return: Float64, discount amount
        >>> customer = Customer('John Doe', 1200)
        >>> cart = ArrayList<Product>()
        >>> cart.add(Product('product', 14, 23.5))
        >>> order = DiscountStrategy(customer, cart, promotion: DiscountStrategy.FidelityPromo)
        >>> DiscountStrategy.FidelityPromo(order)
        16.45

        */
        if (order.customer.fidelity >= 1000) {
            order.total() * 0.05
        } else {
            0.0
        }
    }

    public static func BulkItemPromo(order: DiscountStrategy): Float64 {
        /*
        Calculate the discount based on bulk item quantity in the order.In the same order, if the quantity of a single item reaches 20 or more, each item will enjoy a 10% discount.
        :param order: DiscountStrategy, the order to apply the discount to
        :return: Float64, discount amount
        >>> customer = Customer('John Doe', 1200)
        >>> cart = ArrayList<Product>()
        >>> cart.add(Product('product', 20, 23.5))
        >>> order = DiscountStrategy(customer, cart, promotion: DiscountStrategy.BulkItemPromo)
        >>> DiscountStrategy.BulkItemPromo(order)
        47.0

        */
        var discount: Float64 = 0.0
        for (i in 0..order.cart.size) {
            let item = order.cart[i]
            if (item.quantity >= 20) {
                discount = discount + item.quantity * item.price * 0.1
            }
        }
        discount
    }

    public static func LargeOrderPromo(order: DiscountStrategy): Float64 {
        /*
        Calculate the discount based on the number of different products in the order.If the quantity of different products in the order reaches 10 or more, the entire order will enjoy a 7% discount.
        :param order: DiscountStrategy, the order to apply the discount to
        :return: Float64, discount amount
        >>> customer = Customer('John Doe', 1200)
        >>> cart = ArrayList<Product>()
        >>> cart.add(Product('product', 14, 23.5))
        >>> order = DiscountStrategy(customer, cart, promotion: DiscountStrategy.LargeOrderPromo)
        >>> DiscountStrategy.LargeOrderPromo(order)
        0.0

        */
        let names = HashSet<String>([])
        for (i in 0..order.cart.size) {
            names.add(order.cart[i].name)
        }
        if (names.size >= 10) {
            order.total() * 0.07
        } else {
            0.0
        }
    }
}

import std.collection.*

class EightPuzzle {

    /*
    This class is an implementation of the classic 8-puzzle game, including methods for finding the blank tile, making moves, getting possible moves, and solving the puzzle using a breadth-first search algorithm.
    */

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        /*
        Initializing the initial state of Eight Puzzle Game, stores in attribute this.initial_state.
        And set the goal state of this game, stores in this.goal_state. In this case, set the size as 3*3
        :param initial_state: a 3*3 size list of Integer, stores the initial state
        */
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([1, 2, 3]),
            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        /*
        Find the blank position of current state, which is the 0 element.
        :param state: a 3*3 size list of Integer, stores the current state.
        :return i, j: two Integers, represent the coordinate of the blank block.
        >>> eightPuzzle = EightPuzzle(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        >>> eightPuzzle.find_blank(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        (2, 1)
        */
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        // Fallback (should not happen for valid states)
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        /*
        Find the blank block, then makes the board moves forward the given direction.
        :param state: a 3*3 size list of Integer, stores the state before moving.
        :param direction: String, only has 4 direction "up", "down", "left", "right"
        :return new_state: a 3*3 size list of Integer, stores the state after moving.
        >>> eightPuzzle.move(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]), "left")
        [[2, 3, 4], [5, 8, 1], [0, 6, 7]]
        */
        let (bi, bj) = this.find_blank(state)
        // Deep copy the state
        var new_state = ArrayList<ArrayList<Int64>>([])
        for (i in 0..state.size) {
            var row = ArrayList<Int64>([])
            for (j in 0..state[i].size) {
                row.add(state[i][j], at: row.size)
            }
            new_state.add(row, at: new_state.size)
        }

        match (direction) {
            case "up" => {
                let tmp = new_state[bi - 1][bj]
                new_state[bi - 1][bj] = new_state[bi][bj]
                new_state[bi][bj] = tmp
            }
            case "down" => {
                let tmp = new_state[bi + 1][bj]
                new_state[bi + 1][bj] = new_state[bi][bj]
                new_state[bi][bj] = tmp
            }
            case "left" => {
                let tmp = new_state[bi][bj - 1]
                new_state[bi][bj - 1] = new_state[bi][bj]
                new_state[bi][bj] = tmp
            }
            case "right" => {
                let tmp = new_state[bi][bj + 1]
                new_state[bi][bj + 1] = new_state[bi][bj]
                new_state[bi][bj] = tmp
            }
            case _ => {
                // Invalid direction; return the original copied state
            }
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        /*
        According the current state, find all the possible moving directions. Only has 4 direction "up", "down", "left", "right".
        :param state: a 3*3 size list of Integer, stores the current state.
        :return moves: a list of String, store all the possible moving directions according to the current state.
        >>> eightPuzzle.get_possible_moves(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        ["up", "left", "right"]
        */
        let (i, j) = this.find_blank(state)
        var moves = ArrayList<String>([])
        if (i > 0) {
            moves.add("up", at: moves.size)
        }
        if (i < 2) {
            moves.add("down", at: moves.size)
        }
        if (j > 0) {
            moves.add("left", at: moves.size)
        }
        if (j < 2) {
            moves.add("right", at: moves.size)
        }
        return moves
    }

    public func solve(): ArrayList<String> {
        /*
        Use BFS algorithm to find the path solution which makes the initial state to the goal method.
        Maintain a list as a queue, named as open_list, append the initial state.
        Always visit and pop the 0 index element, invoke get_possible_moves method find all the possible directions.
        Traversal the possible_moves list and invoke move method to get several new states.Then append them.
        redo the above steps until the open_list is empty or the state has changed to the goal state.
        :return path: list of String, the solution to the goal state.
        >>> eightPuzzle = EightPuzzle(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 0, 8])]))
        >>> eightPuzzle.solve()
        ["right"]
        */
        var open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>([])
        var closed_list = ArrayList<ArrayList<ArrayList<Int64>>>([])
        open_list.add((this.initial_state, ArrayList<String>([])), at: open_list.size)

        var idx: Int64 = 0
        while (idx < open_list.size) {
            let entry = open_list[idx]
            let current_state = entry[0]
            let path = entry[1]

            // check goal
            if (this.states_equal(current_state, this.goal_state)) {
                return path
            }

            // mark visited
            closed_list.add(this.copy_state(current_state), at: closed_list.size)

            let moves = this.get_possible_moves(current_state)
            for (mi in 0..moves.size) {
                let mv = moves[mi]
                let new_state = this.move(current_state, mv)
                if (!this.contains_state(closed_list, new_state)) {
                    // build new path
                    var new_path = ArrayList<String>([])
                    for (pi in 0..path.size) {
                        new_path.add(path[pi], at: new_path.size)
                    }
                    new_path.add(mv, at: new_path.size)
                    open_list.add((new_state, new_path), at: open_list.size)
                }
            }

            idx = idx + 1
        }

        // No solution found; return empty path
        return ArrayList<String>([])
    }

    // Helper: deep copy a 3x3 state
    private func copy_state(state: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Int64>> {
        var cp = ArrayList<ArrayList<Int64>>([])
        for (i in 0..state.size) {
            var row = ArrayList<Int64>([])
            for (j in 0..state[i].size) {
                row.add(state[i][j], at: row.size)
            }
            cp.add(row, at: cp.size)
        }
        return cp
    }

    // Helper: compare two 3x3 states for equality
    private func states_equal(a: ArrayList<ArrayList<Int64>>, b: ArrayList<ArrayList<Int64>>): Bool {
        if (a.size != b.size) {
            return false
        }
        for (i in 0..a.size) {
            if (a[i].size != b[i].size) {
                return false
            }
            for (j in 0..a[i].size) {
                if (a[i][j] != b[i][j]) {
                    return false
                }
            }
        }
        return true
    }

    // Helper: check whether a state is contained in a list of states
    private func contains_state(list: ArrayList<ArrayList<ArrayList<Int64>>>, state: ArrayList<ArrayList<Int64>>): Bool {
        for (k in 0..list.size) {
            if (this.states_equal(list[k], state)) {
                return true
            }
        }
        return false
    }
}

import std.time.DateTime
import std.collection.*

class EmailClient {

    /*
    This is a class that serves as an email client, implementing functions such as checking emails, determining whether there is sufficient space, and cleaning up space
    */

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        /*
        Initializes the EmailClient class with the email address and the capacity of the email box.
        :param addr: The email address, String.
        :param capacity: The capacity of the email box, Int64.
        */
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        /*
        Sends an email to the given email address.
        :param recv: The email address of the receiver, String.
        :param content: The content of the email, String.
        :param size: The size of the email, Int64.
        :return: true if the email is sent successfully, false if the receiver's email box is full.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> sender.send_to(receiver, 'Hello', 10)
        true
        >>> receiver.inbox
        {'sender': 'sender@example.com', 'receiver': 'receiver@example.com', 'content': 'Hello', 'size': 10, 'time': '2023-07-13 11:36:40', 'state': 'unread'}

        */
        if (!recv.is_full_with_one_more_email(size)) {
            let email = HashMap<String, Any>()
            email.add("sender", this.addr)
            email.add("receiver", recv.addr)
            email.add("content", content)
            email.add("size", size)
            email.add("time", DateTime.now())
            email.add("state", "unread")
            recv.inbox.add(email, at: recv.inbox.size)
            true
        } else {
            this.clear_inbox(size)
            false
        }
    }

    public func fetch(): HashMap<String, Any> {
        /*
        Retrieves the first unread email in the email box and marks it as read.
        :return: The first unread email in the email box, HashMap<String, Any>
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('sender', 'sender@example.com'), ('receiver', 'receiver@example.com'), ('content', 'Hello'), ('size', 10), ('time', '2023-07-13 11:36:40'), ('state', 'unread')])])
        >>> receiver.fetch()
        {'sender': 'sender@example.com', 'receiver': 'receiver@example.com', 'content': 'Hello', 'size': 10, 'time': '2023-07-13 11:36:40', 'state': 'read'}

        */
        if (this.inbox.size == 0) {
            return HashMap<String, Any>()
        }
        for (i in 0..this.inbox.size) {
            var email = this.inbox[i]
            let st: String = email["state"] as String
            if (st == "unread") {
                email.add("state", "read")
                this.inbox[i] = email
                return email
            }
        }
        HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        /*
        Determines whether the email box is full after adding an email of the given size.
        :param size: The size of the email, Int64.
        :return: true if the email box is full, false otherwise.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.is_full_with_one_more_email(10)
        false

        */
        let occupied_size = this.get_occupied_size()
        (occupied_size + size) > this.capacity
    }

    public func get_occupied_size(): Int64 {
        /*
        Gets the total size of the emails in the email box.
        :return: The total size of the emails in the email box, Int64.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> sender.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('sender', 'sender@example.com'), ('receiver', 'receiver@example.com'), ('content', 'Hello'), ('size', 10), ('time', DateTime.now()), ('state', 'unread')])])
        >>> sender.get_occupied_size()
        10

        */
        var occupied_size: Int64 = 0
        for (i in 0..this.inbox.size) {
            let email = this.inbox[i]
            let s: Int64 = email["size"] as Int64
            occupied_size = occupied_size + s
        }
        occupied_size
    }

    public func clear_inbox(size: Int64): Unit {
        /*
        Clears the email box by deleting the oldest emails until the email box has enough space to accommodate the given size.
        :param size: The size of the email, Int64.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('size', 10)]), HashMap<String, Any>([('size', 20)]), HashMap<String, Any>([('size', 15)])])
        >>> receiver.clear_inbox(30)
        >>> receiver.inbox
        [{'size': 15}]

        */
        if (this.addr == "") {
            return
        }
        var freed_space: Int64 = 0
        while (freed_space < size && this.inbox.size > 0) {
            let email = this.inbox[0]
            let s: Int64 = email["size"] as Int64
            freed_space = freed_space + s
            this.inbox.remove(at: 0)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    private func find_index(arr: Array<Rune>, ch: Rune): Int64 {
        var pos: Int64 = -1
        for (i in 0..arr.size) {
            if (arr[i] == ch) {
                pos = i
            }
        }
        return pos
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        let lower_arr = "abcdefghijklmnopqrstuvwxyz".toRuneArray()
        let upper_arr = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".toRuneArray()
        let runes = plaintext.toRuneArray()
        // normalize shift to [0, 25]
        let s_mod: Int64 = ((shift % 26) + 26) % 26

        var result: String = ""
        for (i in 0..runes.size) {
            let c: Rune = runes[i]
            let idx_lower: Int64 = find_index(lower_arr, c)
            if (idx_lower != -1) {
                let new_idx: Int64 = (idx_lower + s_mod) % 26
                let new_char: Rune = lower_arr[new_idx]
                result = result + "${new_char}"
            } else {
                let idx_upper: Int64 = find_index(upper_arr, c)
                if (idx_upper != -1) {
                    let new_idx2: Int64 = (idx_upper + s_mod) % 26
                    let new_char2: Rune = upper_arr[new_idx2]
                    result = result + "${new_char2}"
                } else {
                    result = result + "${c}"
                }
            }
        }
        return result
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        let lower_arr = "abcdefghijklmnopqrstuvwxyz".toRuneArray()
        let upper_arr = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".toRuneArray()
        let key_runes = this.key.toRuneArray()
        let nkey: Int64 = key_runes.size
        if (nkey == 0) {
            return plain_text
        }

        var result: String = ""
        var key_index: Int64 = 0
        let runes = plain_text.toRuneArray()

        for (i in 0..runes.size) {
            let c: Rune = runes[i]
            let idx_lower: Int64 = find_index(lower_arr, c)
            let idx_upper: Int64 = find_index(upper_arr, c)

            if (idx_lower != -1 || idx_upper != -1) {
                let key_char: Rune = key_runes[key_index % nkey]
                var shift: Int64 = find_index(lower_arr, key_char)
                if (shift == -1) {
                    shift = find_index(upper_arr, key_char)
                }
                if (shift == -1) {
                    shift = 0
                }

                if (idx_lower != -1) {
                    let new_idx: Int64 = (idx_lower + shift) % 26
                    let new_char: Rune = lower_arr[new_idx]
                    result = result + "${new_char}"
                } else {
                    let new_idx: Int64 = (idx_upper + shift) % 26
                    let new_char: Rune = upper_arr[new_idx]
                    result = result + "${new_char}"
                }
                key_index = key_index + 1
            } else {
                result = result + "${c}"
            }
        }
        return result
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        let runes = plain_text.toRuneArray()
        let n: Int64 = runes.size
        if (rails <= 1 || n == 0) {
            return plain_text
        }

        var result: String = ""
        let cycle: Int64 = 2 * (rails - 1)

        for (row in 0..rails) {
            var i: Int64 = row
            while (i < n) {
                result = result + "${runes[i]}"
                if (row != 0 && row != rails - 1) {
                    let j: Int64 = i + cycle - 2 * row
                    if (j < n) {
                        result = result + "${runes[j]}"
                    }
                }
                i = i + cycle
            }
        }
        return result
    }
}

import std.collection.*
import std.math.numeric.Decimal

class ExpressionCalculator {

    /*
    This is a class in Cangjie that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    */

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        :param expression: String, the postfix expression to be calculated
        :return: Float64, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0
        */
        // Prepare postfix tokens
        this.prepare(this.transform(expression))

        // Evaluate postfix
        var result_stack = ArrayList<Decimal>()
        var i: Int64 = 0
        for (i in 0..postfix_stack.size) {
            let tok = postfix_stack[i]
            if (!ExpressionCalculator.is_operator(tok)) {
                let num_str = ExpressionCalculator.replace_tilde_with_minus(tok)
                result_stack.add(Decimal(num_str), at: result_stack.size)
            } else {
                // Pop two operands
                let second_value = result_stack.remove(at: result_stack.size - 1)
                let first_value = result_stack.remove(at: result_stack.size - 1)
                let temp_result = ExpressionCalculator._calculate(first_value, second_value, tok)
                result_stack.add(temp_result, at: result_stack.size)
            }
        }

        // Final result
        if (result_stack.size == 0) {
            return 0.0
        } else {
            let final_decimal = result_stack[0]
            // Convert Decimal to Float64 (conservative assumption that casting works)
            return final_decimal as Float64
        }
    }

    public func prepare(expression: String): Unit {
        /*
        Prepare the infix expression for conversion to postfix notation
        :param expression: String, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")

        expression_calculator.postfix_stack = ['2', '3', '4', '*', '+']
        */
        // Reset postfix stack
        postfix_stack = ArrayList<String>()

        // Operator stack, using "," as sentinel
        var op_stack = ArrayList<String>([","])

        // Build tokens by scanning characters
        var current_token: String = ""
        let arr = expression.toRuneArray()
        var i: Int64 = 0
        for (i in 0..arr.size) {
            let c = arr[i]
            let cs: String = "${c}"
            if (ExpressionCalculator.is_operator(cs)) {
                // flush accumulated token
                if (current_token != "") {
                    postfix_stack.add(current_token, at: postfix_stack.size)
                    current_token = ""
                }

                let current_op = cs
                var peek_op = op_stack[op_stack.size - 1]
                if (current_op == ")") {
                    while (op_stack[op_stack.size - 1] != "(") {
                        let popped = op_stack.remove(at: op_stack.size - 1)
                        postfix_stack.add(popped, at: postfix_stack.size)
                    }
                    // Pop '('
                    _ = op_stack.remove(at: op_stack.size - 1)
                } else {
                    while (current_op != "(" && peek_op != "," && this.compare(current_op, peek_op)) {
                        let popped = op_stack.remove(at: op_stack.size - 1)
                        postfix_stack.add(popped, at: postfix_stack.size)
                        peek_op = op_stack[op_stack.size - 1]
                    }
                    // Push current operator
                    op_stack.add(current_op, at: op_stack.size)
                }
            } else {
                // part of a number or symbol (including '~' unary minus marker, digits, '.', 'E', 'e')
                current_token = "${current_token}${c}"
            }
        }

        // Flush last token if present
        if (current_token != "") {
            postfix_stack.add(current_token, at: postfix_stack.size)
            current_token = ""
        }

        // Pop remaining operators
        while (op_stack[op_stack.size - 1] != ",") {
            let popped = op_stack.remove(at: op_stack.size - 1)
            postfix_stack.add(popped, at: postfix_stack.size)
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        :param c: String, the character to be checked
        :return: Bool, true if the character is an operator, false otherwise
        >>> ExpressionCalculator.is_operator("+")
        true
        */
        c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        /*
        Compare the precedence of two operators
        :param cur: String, the current operator
        :param peek: String, the operator at the top of the operator stack
        :return: Bool, true if the current operator has higher or equal precedence, false otherwise
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.compare("+", "-")
        true
        */
        let cur_norm = if (cur == "%") { "/" } else { cur }
        let peek_norm = if (peek == "%") { "/" } else { peek }
        ExpressionCalculator.precedence(peek_norm) >= ExpressionCalculator.precedence(cur_norm)
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        /*
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: Decimal, the first operand
        :param second_value: Decimal, the second operand
        :param current_op: String, the operator
        :return: Decimal, the calculated result
        >>> ExpressionCalculator._calculate("2", "3", "+")
        5.0
        */
        if (current_op == "+") {
            first_value + second_value
        } else if (current_op == "-") {
            first_value - second_value
        } else if (current_op == "*") {
            first_value * second_value
        } else if (current_op == "/") {
            first_value / second_value
        } else if (current_op == "%") {
            first_value % second_value
        } else {
            // Unexpected operator; keep conservative behavior
            throw("Unexpected operator: ${current_op}")
        }
    }

    public static func transform(expression: String): String {
        /*
        Transform the infix expression to a format suitable for conversion
        :param expression: String, the infix expression to be transformed
        :return: String, the transformed expression
        >>> ExpressionCalculator.transform("2 + 3 * 4")
        "2+3*4"
        */
        // 1) Remove whitespaces
        var compact: String = ""
        let runes = expression.toRuneArray()
        var i: Int64 = 0
        for (i in 0..runes.size) {
            let r = runes[i]
            if (r != r' ' && r != r'\t' && r != r'\n' && r != r'\r') {
                compact = "${compact}${r}"
            }
        }

        // 2) Remove trailing '=' if present
        let arr1 = compact.toRuneArray()
        if (arr1.size > 0 && arr1[arr1.size - 1] == r'=') {
            var j: Int64 = 0
            var compact2: String = ""
            for (j in 0..(arr1.size - 1)) {
                compact2 = "${compact2}${arr1[j]}"
            }
            compact = compact2
        }

        // 3) Mark unary '-' as '~'
        var arr2 = compact.toRuneArray()
        var k: Int64 = 0
        for (k in 0..arr2.size) {
            let c = arr2[k]
            if (c == r'-') {
                if (k == 0) {
                    arr2[k] = r'~'
                } else {
                    let prev_c = arr2[k - 1]
                    if (prev_c == r'+' || prev_c == r'-' || prev_c == r'*' || prev_c == r'/' ||
                        prev_c == r'(' || prev_c == r'E' || prev_c == r'e') {
                        arr2[k] = r'~'
                    }
                }
            }
        }

        // 4) Special case: "~(" at the beginning => "-(" with a leading 0
        if (arr2.size > 1 && arr2[0] == r'~' && arr2[1] == r'(') {
            arr2[0] = r'-'
            var s: String = ""
            var z: Int64 = 0
            for (z in 0..arr2.size) {
                s = "${s}${arr2[z]}"
            }
            "0${s}"
        } else {
            var s2: String = ""
            var t: Int64 = 0
            for (t in 0..arr2.size) {
                s2 = "${s2}${arr2[t]}"
            }
            s2
        }
    }

    public static func precedence(op: String): Int64 {
        // Mirror the Python operat_priority mapping, with '%' treated as '/'
        if (op == "(") { 0 }
        else if (op == ")") { 3 }
        else if (op == "*") { 2 }
        else if (op == "+") { 1 }
        else if (op == ",") { -1 }
        else if (op == "-") { 1 }
        else if (op == "/") { 2 }
        else if (op == "%") { 2 }
        else { -1 }
    }

    public static func replace_tilde_with_minus(s: String): String {
        var out: String = ""
        let a = s.toRuneArray()
        var i: Int64 = 0
        for (i in 0..a.size) {
            if (a[i] == r'~') {
                out = "${out}-"
            } else {
                out = "${out}${a[i]}"
            }
        }
        out
    }
}

import std.collection.*

class FitnessTracker {

    /*
    This is a class as fitness tracker that implements to calculate BMI (Body Mass Index) and calorie intake based on the user's height, weight, age, and sex.
    */

    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        /*
        Initialize the class with height, weight, age, and sex, and calculate the BMI standard based on sex, and male is 20-25, female is 19-24.
        */
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        /*
        Calculate the BMI based on the height and weight.
        :return: BMI,which is the weight divide by the square of height, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.get_BMI()
        21.604938271604937

        */
        return this.weight / (this.height * this.height)
    }

    public func condition_judge(): Int64 {
        /*
        Judge the condition of the user based on the BMI standard.
        :return: 1 if the user is too fat, -1 if the user is too thin, 0 if the user is normal, Int64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.condition_judge()
        -1

        */
        let BMI = this.get_BMI()
        let BMI_range: ArrayList<Int64> = if (this.sex == "male") {
            this.BMI_std[0]["male"]
        } else {
            this.BMI_std[1]["female"]
        }
        if (BMI > Float64(BMI_range[1])) {
            return 1
        } else if (BMI < Float64(BMI_range[0])) {
            return -1
        } else {
            return 0
        }
    }

    public func calculate_calorie_intake(): Float64 {
        /*
        Calculate the calorie intake based on the user's condition and BMR (Basal Metabolic Rate),BMR is calculated based on the user's height, weight, age, and sex,male is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) + Float64(5),female is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) - Float64(161), and the calorie intake is calculated based on the BMR and the user's condition,if the user is too fat, the calorie intake is BMR * 1.2, if the user is too thin, the calorie intake is BMR * 1.6, if the user is normal, the calorie intake is BMR * 1.4.
        :return: calorie intake, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.calculate_calorie_intake()
        986.0

        */
        let BMR: Float64 = if (this.sex == "male") {
            Float64(10) * this.weight + Float64(6.25) * this.height - Float64(5) * Float64(this.age) + Float64(5)
        } else {
            Float64(10) * this.weight + Float64(6.25) * this.height - Float64(5) * Float64(this.age) - Float64(161)
        }
        let cond = this.condition_judge()
        var calorie_intake: Float64 = 0.0
        if (cond == 1) {
            calorie_intake = BMR * Float64(1.2)  // Sedentary lifestyle
        } else if (cond == -1) {
            calorie_intake = BMR * Float64(1.6)  // Active lifestyle
        } else {
            calorie_intake = BMR * Float64(1.4)  // Moderate lifestyle
        }
        return calorie_intake
    }
}

main() {
    let fitnessTracker = FitnessTracker(Float64(1.8), Float64(70.0), Int64(20), "male")
    println(fitnessTracker.get_BMI())
    println(fitnessTracker.condition_judge())
    println(fitnessTracker.calculate_calorie_intake())
}

import std.collection.*

class GomokuGame {

    /*
    This class is an implementation of a Gomoku game, supporting for making moves, checking for a winner, and checking if there are five consecutive symbols on the game board.
    */

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        /*
        Initializes the game with a given board size.
        It initializes the board with empty spaces and sets the current player symbol as 'X'.
        */
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            this.board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        /*
        Makes a move at the given row and column.
        If the move is valid, it places the current player's symbol on the board
        and changes the current player to the other player (if the current player is 'X', then it becomes 'O' and vice versa).
        :param row: Int64, the row index of this move
        :param col: Int64, the column index
        return: true if the move is valid, or false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> gomokuGame.make_move(5, 5)
        true
        >>> gomokuGame.make_move(5, 5)
        false
        */
        if (row < 0 || row >= this.board_size || col < 0 || col >= this.board_size) {
            return false
        }
        if (this.board[row][col] == " ") {
            this.board[row][col] = this.current_player
            this.current_player = if (this.current_player == "X") { "O" } else { "X" }
            return true
        } else {
            return false
        }
    }

    public func check_winner(): Option<String> {
        /*
        Checks if there is a winner by looking for five in a row in all directions (horizontal, vertical, diagonal).
        return: the symbol of the winning player (either 'X' or 'O') if there is a winner, or None otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame.check_winner()
        'X'
        */
        let directions: Array<(Int64, Int64)> = [(0, 1), (1, 0), (1, 1), (1, -1)]
        for (row in 0..this.board_size) {
            for (col in 0..this.board_size) {
                let cell: String = this.board[row][col]
                if (cell != " ") {
                    for (i in 0..directions.size) {
                        let dir: (Int64, Int64) = directions[i]
                        if (this._check_five_in_a_row(row, col, dir)) {
                            return Some<String>(cell)
                        }
                    }
                }
            }
        }
        return None<String>
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        /*
        checks if there are five consecutive symbols of the same player in a row starting from a given cell in a given direction (horizontal, vertical, diagonal).
        Counts the number of consecutive symbols in that direction starting from the given cell,
        :param row: Int64, row of the given cell
        :param col: Int64, column of the given cell
        :param direction: tuple, (Int64, Int64), named as (dx, dy). Row and col will plus several dx and dy repectively.
        :return: true if there are five consecutive symbols of the same player, and false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame._check_five_in_a_row(5, 1, (0, 1))
        true
        >>> gomokuGame._check_five_in_a_row(5, 1, (1, 1))
        false
        */
        let dx: Int64 = direction[0]
        let dy: Int64 = direction[1]
        let symbol: String = this.board[row][col]
        var count: Int64 = 1
        for (i in 1..5) {
            let new_row: Int64 = row + dx * i
            let new_col: Int64 = col + dy * i
            if (new_row < 0 || new_row >= this.board_size || new_col < 0 || new_col >= this.board_size) {
                return false
            }
            if (this.board[new_row][new_col] != symbol) {
                return false
            }
            count = count + 1
        }
        return count == 5
    }
}

import std.collection.*

class Hotel {

    /*
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    */

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        /*
        Initialize the three fields in Hotel System.
        name is the hotel name.
        available_rooms stores the remaining rooms in the hotel
        booked_rooms stores the rooms that have been booked and the person's name who booked rooms.
        >>> hotel.name
        'peace hotel'
        >>> hotel.available_rooms
        available_rooms = {'single': 5, 'double': 3}
        >>> hotel.booked_rooms
        {'single': {'guest 1': 2, 'guest 2':1}, 'double': {'guest1': 1}}
        */
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        /*
        Check if there are any rooms of the specified type available.
        if rooms are adequate, modify available_rooms and booked_rooms and finish booking, or fail to book otherwise.
        :param room_type: String
        :param room_number: Int64, the expected number of specified type rooms to be booked
        :param name: String, guest name
        :return: if number of rooms about to be booked doesn't exceed the remaining rooms, return str 'Success!'
                if exceeds but quantity of available rooms is not equal to zero, return Int64.toString() (the remaining quantity of this room type).
                if exceeds and quantity is zero or the room_type isn't in available_room, return 'false'.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.book_room('single', 1, 'guest 1')
        'Success!'
        >>> hotel.book_room('single', 5, 'guest 1')
        '4'
        >>> hotel.book_room('single', 4, 'guest 1')
        'Success!'
        >>> hotel.book_room('single', 1, 'guest 1')
        'false'
        >>> hotel.book_room('triple', 1, 'guest 1')
        'false'
        */
        let avail_opt = this.available_rooms.get(room_type)
        match (avail_opt) {
            case Some<Int64>(avail) => {
                if (room_number <= avail) {
                    let inner = this.booked_rooms.get(room_type) ?? HashMap<String, Int64>()
                    inner.add(name, room_number)
                    this.booked_rooms.add(room_type, inner)
                    this.available_rooms.add(room_type, avail - room_number)
                    return "Success!"
                } else if (avail != 0) {
                    return "${avail}"
                } else {
                    return "false"
                }
            }
            case None<Int64> => {
                return "false"
            }
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        /*
        Check if the room of the specified type and number is booked by the person named name.
        Remove this name when check in successfuly(room_number is equal to specific person's booked_rooms. When the actual check in quantity (room_number) is less than the booked quantity, number in booked_rooms will be booked quantity minus actual quantity
        :param room_type: String, check in room type
        :param room_number: Int64, check in room number
        :param name: String, person name
        :return false: only if the room_type is not in the booked_rooms or room_number is higher than quantity in booked rooms.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.book_room('single', 1, 'guest 1')
        true
        >>> hotel.check_in('single', 2, 'guest 1')
        false
        >>> hotel.check_in('single', 1, 'guest 1')
        true
        >>> hotel.booked_rooms
        {'single': {}}
        */
        let inner_opt = this.booked_rooms.get(room_type)
        match (inner_opt) {
            case Some<HashMap<String, Int64>>(inner) => {
                let booked_opt = inner.get(name)
                match (booked_opt) {
                    case Some<Int64>(booked) => {
                        if (room_number > booked) {
                            return false
                        } else if (room_number == booked) {
                            inner.remove(name)
                            this.booked_rooms.add(room_type, inner)
                            return true
                        } else {
                            inner.add(name, booked - room_number)
                            this.booked_rooms.add(room_type, inner)
                            return true
                        }
                    }
                    case None<Int64> => {
                        return false
                    }
                }
            }
            case None<HashMap<String, Int64>> => {
                return false
            }
        }
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        /*
        Check out rooms, add number for specific type in available_rooms.
        If room_type is new, add new type in available_rooms.
        :param room_type: String, check out room type
        :param room_number: Int64, check out room number
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.check_out('single', 2)
        >>> hotel.available_rooms
        {'single': 7, 'double': 3}
        >>> hotel.check_out('triple', 2)
        >>> hotel.available_rooms
        {'single': 7, 'double': 3, 'triple': 2}
        */
        let avail = this.available_rooms.get(room_type) ?? 0
        this.available_rooms.add(room_type, avail + room_number)
    }

    public func get_available_rooms(room_type: String): Int64 {
        /*
        Get the number of specific type of available rooms.
        :param room_type: String, the room type that want to know
        :return: Int64, the remaining number of this type rooms.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.get_available_rooms('single')
        5
        */
        let v = this.available_rooms.get(room_type) ?? 0
        return v
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Employee <: Equatable<Employee> {

    /*
    This is a class representing an employee with attributes such as name, position, department, and salary.
    */

    var name: String
    var position: String
    var department: String
    var salary: Int64

    public init(name: String, position: String, department: String, salary: Int64) {
        /*
        Initialize an Employee with name, position, department, and salary.
        :param name: The employee's name, String.
        :param position: The employee's position, String.
        :param department: The employee's department, String.
        :param salary: The employee's salary, Int64.
        */
        this.name = name
        this.position = position
        this.department = department
        this.salary = salary
    }

    public override operator func != (that: Employee): Bool {
        /*
        Check if two Employee objects are not equal.
        :param that: Another Employee object to compare with.
        :return: true if any attribute is different, false otherwise.
        */
        return this.name != that.name || this.position != that.position || this.department != that.department || this.salary != that.salary
    }

    public override operator func == (that: Employee): Bool {
        /*
        Check if two Employee objects are equal.
        :param that: Another Employee object to compare with.
        :return: true if all attributes are the same, false otherwise.
        */
        return this.name == that.name && this.position == that.position && this.department == that.department && this.salary == that.salary
    }
}

class HRManagementSystem {

    /*
    This is a class as personnel management system that implements functions such as adding, deleting, querying, and updating employees
    */

    var employees: HashMap<Int64, Employee>

    public init() {
        /*
        Initialize the HRManagementSystem withan attribute employees, which is an empty dictionary.
        */
        this.employees = HashMap<Int64, Employee>()
    }

    public func add_employee(employee_id: Int64, name: String, position: String, department: String, salary: Int64): Bool {
        /*
        Add a new employee to the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :param name: The employee's name, String.
        :param position: The employee's position, String.
        :param department: The employee's department, String.
        :param salary: The employee's salary, Int64.
        :return: If the employee is already in the HRManagementSystem, returns false, otherwise, returns true.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.add_employee(1, 'John', 'Manager', 'Sales', 100000)
        true
        >>> hrManagementSystem.add_employee(1, 'John', 'Manager', 'Sales', 100000)
        false

        */
        let maybe = this.employees.get(employee_id)
        match (maybe) {
            case Some<Employee>(_ ) => false
            case None<Employee> => {
                let emp = Employee(name, position, department, salary)
                this.employees.add(employee_id, emp)
                true
            }
        }
    }

    public func remove_employee(employee_id: Int64): Bool {
        /*
        Remove an employee from the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :return: If the employee is already in the HRManagementSystem, returns true, otherwise, returns false.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.remove_employee(1)
        true
        >>> hrManagementSystem.remove_employee(2)
        false

        */
        match (this.employees.get(employee_id)) {
            case Some<Employee>(_ ) => {
                this.employees.remove(employee_id)
                true
            }
            case None<Employee> => false
        }
    }

    public func update_employee(employee_id: Int64, employee_info: HashMap<String, Any>): Bool {
        /*
        Update an employee's information in the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :param employee_info: The employee's information, HashMap<String, Any>.
        :return: If the employee is already in the HRManagementSystem, returns true, otherwise, returns false.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.update_employee(1, HashMap<String, Any>([('name', 'John Doe'), ('position', 'Manager'), ('department', 'Sales'), ('salary', 20000)]))
        true
        >>> hrManagementSystem.update_employee(2, HashMap<String, Any>([('name', 'John Doe'), ('position', 'Manager'), ('department', 'Sales'), ('salary', 20000)]))
        false

        */
        match (this.employees.get(employee_id)) {
            case None<Employee> => false
            case Some<Employee>(emp) => {
                // Validate that all provided keys are recognized
                var known_count: Int64 = 0
                match (employee_info.get("name")) {
                    case Some<Any>(_ ) => { known_count = known_count + 1 }
                    case None<Any> => { }
                }
                match (employee_info.get("position")) {
                    case Some<Any>(_ ) => { known_count = known_count + 1 }
                    case None<Any> => { }
                }
                match (employee_info.get("department")) {
                    case Some<Any>(_ ) => { known_count = known_count + 1 }
                    case None<Any> => { }
                }
                match (employee_info.get("salary")) {
                    case Some<Any>(_ ) => { known_count = known_count + 1 }
                    case None<Any> => { }
                }

                if (known_count != employee_info.size) {
                    false
                } else {
                    // Apply updates (subset allowed)
                    match (employee_info.get("name")) {
                        case Some<Any>(v) => { emp.name = v as String }
                        case None<Any> => { }
                    }
                    match (employee_info.get("position")) {
                        case Some<Any>(v) => { emp.position = v as String }
                        case None<Any> => { }
                    }
                    match (employee_info.get("department")) {
                        case Some<Any>(v) => { emp.department = v as String }
                        case None<Any> => { }
                    }
                    match (employee_info.get("salary")) {
                        case Some<Any>(v) => { emp.salary = v as Int64 }
                        case None<Any> => { }
                    }
                    // Persist the updated employee
                    this.employees.add(employee_id, emp)
                    true
                }
            }
        }
    }

    public func get_employee(employee_id: Int64): Option<Employee> {
        /*
        Get an employee's information from the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :return: If the employee is already in the HRManagementSystem, returns the employee's information, otherwise, returns None.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.get_employee(1)
        Employee('John', 'Manager', 'Sales', 100000)
        >>> hrManagementSystem.get_employee(2)
        None

        */
        this.employees.get(employee_id)
    }

    public func list_employees(): ArrayList<Employee> {
        /*
        List all employees' information in the HRManagementSystem.
        :return: A list of all employees' information, ArrayList<Employee>.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees = HashMap<Int64, Employee>([(1, Employee('John', 'Manager', 'Sales', 100000))])
        >>> hrManagementSystem.list_employees()
        ArrayList<Employee>([Employee('John', 'Manager', 'Sales', 100000)])

        */
        // Conservatively assume HashMap provides values() returning all values.
        this.employees.values()
    }
}

import std.collection.*

class Interpolation {

    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        /*
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, ArrayList<Float64>.
        :param y: The y-coordinate of the data point, ArrayList<Float64>.
        :param x_interp: The x-coordinate of the interpolation point, ArrayList<Float64>.
        :return: The y-coordinate of the interpolation point, ArrayList<Float64>.
        >>> Interpolation.interpolate_1d(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([1.5, 2.5]))
        [1.5, 2.5]
        */
        let result = ArrayList<Float64>([])
        let n = x.size
        let m = x_interp.size

        for (k in 0..m) {
            let xi = x_interp[k]
            var appended: Bool = false
            for (i in 0..(n - 1)) {
                let x0 = x[i]
                let x1 = x[i + 1]
                if (x0 <= xi && xi <= x1) {
                    let y0 = y[i]
                    let y1 = y[i + 1]
                    let yi = y0 + (y1 - y0) * (xi - x0) / (x1 - x0)
                    result.add(yi, at: result.size)
                    appended = true
                    break
                }
            }
            // if not appended, skip (out-of-range xi)
        }

        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        /*
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, ArrayList<Float64>.
        :param y: The y-coordinate of the data point, ArrayList<Float64>.
        :param z: The z-coordinate of the data point, ArrayList<ArrayList<Float64>>.
        :param x_interp: The x-coordinate of the interpolation point, ArrayList<Float64>.
        :param y_interp: The y-coordinate of the interpolation point, ArrayList<Float64>.
        :return: The z-coordinate of the interpolation point, ArrayList<Float64>.
        >>> let x = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> let y = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> let z = ArrayList<ArrayList<Float64>>([ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]), ArrayList<Float64>([7.0, 8.0, 9.0])])
        >>> let x_interp = ArrayList<Float64>([1.5, 2.5])
        >>> let y_interp = ArrayList<Float64>([1.5, 2.5])
        >>> let result = Interpolation.interpolate_2d(x, y, z, x_interp, y_interp)
        >>> result
        [3.0, 7.0]
        */
        let result = ArrayList<Float64>([])
        let nx = x.size
        let ny = y.size
        let m = x_interp.size

        for (k in 0..m) {
            let xi = x_interp[k]
            let yi = y_interp[k]
            var found: Bool = false

            for (i in 0..(nx - 1)) {
                let x0 = x[i]
                let x1 = x[i + 1]
                if (x0 <= xi && xi <= x1) {
                    for (j in 0..(ny - 1)) {
                        let y0 = y[j]
                        let y1 = y[j + 1]
                        if (y0 <= yi && yi <= y1) {
                            let z00 = z[i][j]
                            let z01 = z[i][j + 1]
                            let z10 = z[i + 1][j]
                            let z11 = z[i + 1][j + 1]
                            let denom = (x1 - x0) * (y1 - y0)
                            let zi = (z00 * (x1 - xi) * (y1 - yi) +
                                      z10 * (xi - x0) * (y1 - yi) +
                                      z01 * (x1 - xi) * (yi - y0) +
                                      z11 * (xi - x0) * (yi - y0)) / denom
                            result.add(zi, at: result.size)
                            found = true
                            break
                        }
                    }
                    if (found) { break }
                }
            }
            // if not found, skip (out-of-range (xi, yi))
        }

        return result
    }
}

import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {

    /*
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    */

    let ip_address: String

    public init(ip_address: String) {
        /*
        Initialize the IP address to the specified address
        :param ip_address:String
        */
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        /*
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: Bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        true
        */
        let parts = this.parse_octets()
        if (parts.size != 4) {
            return false
        }
        for (i in 0..parts.size) {
            let p = parts[i]
            let ov = this.parse_dec(p)
            match (ov) {
                case Some<Int64>(v) => {
                    if (v < 0 || v > 255) {
                        return false
                    }
                }
                case _ => {
                    return false
                }
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        /*
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: ArrayList<String>
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        */
        if (this.is_valid()) {
            return this.parse_octets()
        } else {
            return ArrayList<String>([])
        }
    }

    public func get_binary(): String {
        /*
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: String
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        */
        if (!this.is_valid()) {
            return ""
        }
        let parts = this.parse_octets()
        var out: String = ""
        for (i in 0..parts.size) {
            let p = parts[i]
            let v: Int64 = this.parse_dec(p).getOrThrow()
            let bs = this.to_binary8(v)
            if (i == 0) {
                out = bs
            } else {
                out = out + "." + bs
            }
        }
        return out
    }

    /* Helper: split ip_address by '.' into components (may contain empty tokens) */
    private func parse_octets(): ArrayList<String> {
        var parts = ArrayList<String>([])
        var buf: String = ""
        let arr = this.ip_address.toRuneArray()
        for (i in 0..arr.size) {
            let ch = arr[i]
            if (ch == r'.') {
                parts.add(buf, at: parts.size)
                buf = ""
            } else {
                buf = buf + "${ch}"
            }
        }
        /* add last segment */
        parts.add(buf, at: parts.size)
        return parts
    }

    /* Helper: parse a decimal string into Int64; returns None<Int64> if any non-digit or empty */
    private func parse_dec(s: String): Option<Int64> {
        var value: Int64 = 0
        var length: Int64 = 0
        let arr = s.toRuneArray()
        for (i in 0..arr.size) {
            let ch = arr[i]
            let digit = match (ch) {
                case r'0' => 0
                case r'1' => 1
                case r'2' => 2
                case r'3' => 3
                case r'4' => 4
                case r'5' => 5
                case r'6' => 6
                case r'7' => 7
                case r'8' => 8
                case r'9' => 9
                case _ => -1
            }
            if (digit < 0) {
                return None<Int64>
            }
            value = value * 10 + digit
            length = length + 1
        }
        if (length == 0) {
            return None<Int64>
        }
        return Some<Int64>(value)
    }

    /* Helper: convert 0..255 to 8-bit binary string */
    private func to_binary8(n: Int64): String {
        var v: Int64 = n
        var s: String = ""
        for (i in 0..8) {
            let half: Int64 = v / 2
            let bit: Int64 = v - half * 2
            if (bit == 1) {
                s = "1" + s
            } else {
                s = "0" + s
            }
            v = half
        }
        return s
    }
}

import std.net.dns.*

class IpUtil {

    /*
    This is a class as tool for ip that can be used to obtain the local IP address, validate its validity, and also provides the functionality to retrieve the corresponding hostname.
    */

    public static func is_valid_ipv4(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv4 address.
        :param ip_address: String, the IP address to check
        :return: Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv4('192.168.0.123')
        true
        >>> IpUtil.is_valid_ipv4('256.0.0.0')
        false
        */
        let rs = ip_address.toRuneArray()
        if (rs.size == 0) { return false }

        var dots: Int32 = 0
        var value: Int32 = 0
        var has_digit: Bool = false

        for (i in 0..rs.size) {
            let c = rs[i]
            if (c == r'.') {
                if (!has_digit) { return false }
                if (value < 0 || value > 255) { return false }
                dots = dots + 1
                if (dots > 3) { return false }
                value = 0
                has_digit = false
            } else {
                var d: Int32 = match (c) {
                    case r'0' => 0
                    case r'1' => 1
                    case r'2' => 2
                    case r'3' => 3
                    case r'4' => 4
                    case r'5' => 5
                    case r'6' => 6
                    case r'7' => 7
                    case r'8' => 8
                    case r'9' => 9
                    case _ => -1
                }
                if (d == -1) { return false }
                value = value * 10 + d
                if (value > 255) { return false }
                has_digit = true
            }
        }

        if (!has_digit) { return false }
        if (value < 0 || value > 255) { return false }
        return dots == 3
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv6 address.
        :param ip_address:String, the IP address to check
        :return:Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:0000:0000:8a2e:0370:7334')
        true
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:::8a2e:0370:7334')
        false
        */
        let rs = ip_address.toRuneArray()
        if (rs.size == 0) { return false }

        var groups: Int32 = 0
        var group_len: Int32 = 0
        var saw_double_colon: Bool = false
        var prev_colon: Bool = false

        for (i in 0..rs.size) {
            let c = rs[i]
            if (c == r':') {
                if (prev_colon) {
                    // "::" compression
                    if (saw_double_colon) { return false }
                    saw_double_colon = true
                    prev_colon = false
                    // group_len must be 0 here; no explicit group added
                } else {
                    if (group_len == 0) { return false }
                    groups = groups + 1
                    group_len = 0
                    prev_colon = true
                }
            } else {
                let h: Int32 = match (c) {
                    case r'0' => 0
                    case r'1' => 1
                    case r'2' => 2
                    case r'3' => 3
                    case r'4' => 4
                    case r'5' => 5
                    case r'6' => 6
                    case r'7' => 7
                    case r'8' => 8
                    case r'9' => 9
                    case r'a' => 10
                    case r'b' => 11
                    case r'c' => 12
                    case r'd' => 13
                    case r'e' => 14
                    case r'f' => 15
                    case r'A' => 10
                    case r'B' => 11
                    case r'C' => 12
                    case r'D' => 13
                    case r'E' => 14
                    case r'F' => 15
                    case _ => -1
                }
                if (h == -1) { return false }
                group_len = group_len + 1
                if (group_len > 4) { return false }
                prev_colon = false
            }
        }

        // Trailing single ":" is invalid (unless handled as "::" above)
        if (prev_colon) { return false }

        if (group_len > 0) {
            groups = groups + 1
        }

        if (saw_double_colon) {
            // With compression, total explicit groups must be <= 8
            return groups <= 8
        } else {
            // Without compression, exactly 8 groups must be present
            return groups == 8
        }
    }

    public static func get_hostname(ip_address: String): Option<String> {
        /*
        Get the hostname associated with the given IP address.
        :param ip_address:String, the IP address to get the hostname for
        :return: String, the hostname associated with the IP address
        >>> IpUtil.get_hostname('110.242.68.3')
        'www.baidu.com'
        >>> IpUtil.get_hostname('10.0.0.1')
        None
        */
        // Validate IP first
        if (!IpUtil.is_valid_ipv4(ip_address) && !IpUtil.is_valid_ipv6(ip_address)) {
            return None<String>
        }

        // Reverse DNS lookup (conservatively inferred API)
        // Returns Option<String>: Some<String>(hostname) on success, None<String> on failure.
        let host: Option<String> = DNS.gethostbyaddr(ip_address)
        return host
    }
}

import std.collection.*

interface Equatable<T> {
    operator func ==(that: T): Bool
    operator func !=(that: T): Bool
}

class Resume <: Equatable<Resume> {

    /*
    Represents a candidate's resume containing personal information, skills, and work experience.
    This class is used within the job marketplace system to store and manage applicant data.
    It conforms to the Equatable interface to allow comparison between resume instances.
    */

    let name: String
    let skills: ArrayList<String>
    let experience: String

    public init(name: String, skills: ArrayList<String>, experience: String) {
        this.name = name
        this.skills = skills
        this.experience = experience
    }

    public override operator func != (that: Resume): Bool {
        return this.name != that.name || this.skills != that.skills || this.experience != that.experience
    }

    public override operator func == (that: Resume): Bool {
        return this.name == that.name && this.skills == that.skills && this.experience == that.experience
    }
}

class JobListing <: Equatable<JobListing> {

    /*
    Represents a job listing posted by a company, including the job title, company name, and required skills.
    This class is used in the job marketplace to manage available positions.
