class Snake {

    /*
    The class is a snake game, which allows the snake to move and eat food, and also enables reset, and generate a random food position.
    */

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        /*
        Initialize the length of the snake, screen width, screen height, block size, snake head position, score, and food position.
        :param SCREEN_WIDTH: Int64
        :param SCREEN_HEIGHT: Int64
        :param BLOCK_SIZE: Int64, Size of moving units
        :param food_position: ArrayList<Int64>, representing the position(x, y) of food.
        */
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        /*
        Move the snake in the specified direction. If the new position of the snake's head is equal to the position of the food, then eat the food; If the position of the snake's head is equal to the position of its body, then start over, otherwise insert the new head and trim tail if needed.
        :param direction: ArrayList<Int64>, representing the direction of movement (x, y).
        :return: Unit
        */
        let cur = this.positions[0]
        let dx = direction[0]
        let dy = direction[1]

        let newX = (cur[0] + (dx * this.BLOCK_SIZE)) % this.SCREEN_WIDTH
        let newY = (cur[1] + (dy * this.BLOCK_SIZE)) % this.SCREEN_HEIGHT

        /* Eat food if head reaches food position */
        if (newX == this.food_position[0] && newY == this.food_position[1]) {
            this.eat_food()
        }

        /* Check self-collision with body (excluding the immediate previous head at index 1) */
        var collided: Bool = false
        if (this.positions.size > 2) {
            for (i in 2..this.positions.size) {
                let p = this.positions[i]
                if (p[0] == newX && p[1] == newY) {
                    collided = true
                    break
                }
            }
        }

        if (collided) {
            this.reset()
        } else {
            /* Insert new head at the front */
            this.positions.add(ArrayList<Int64>([newX, newY]), at: 0)
            /* Trim tail if longer than length */
            if (this.positions.size > this.length) {
                this.positions.remove(at: this.positions.size - 1)
            }
        }
    }

    public func random_food_position(): Unit {
        /*
        Randomly generate a new food position, but don't place it on the snake.
        :return: Unit, Change the food position
        */
        let cellsX = this.SCREEN_WIDTH / this.BLOCK_SIZE
        let cellsY = this.SCREEN_HEIGHT / this.BLOCK_SIZE
        while (true) {
            let rx = Random.randint(0, cellsX - 1) * this.BLOCK_SIZE
            let ry = Random.randint(0, cellsY - 1) * this.BLOCK_SIZE
            let candidate = ArrayList<Int64>([rx, ry])
            if (!this.isOnSnake(candidate)) {
                this.food_position = candidate
                break
            }
        }
    }

    public func reset(): Unit {
        /*
        Reset the snake to its initial state. Set the length to 1, the snake head position to ((SCREEN_WIDTH/2), (SCREEN_HEIGHT/2)), the score to 0, and randomly generate new food position.
        :return: Unit
        */
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        /*
        Increase the length of the snake by 1 and increase the score by 100. Randomly generate a new food position, but
        don't place it on the snake.
        :return: Unit
        */
        this.length = this.length + 1
        this.score = this.score + 100
        this.random_food_position()
    }

    public func isOnSnake(pos: ArrayList<Int64>): Bool {
        /*
        Check whether a position overlaps the snake.
        */
        for (i in 0..this.positions.size) {
            let p = this.positions[i]
            if (p[0] == pos[0] && p[1] == pos[1]) {
                return true
            }
        }
        false
    }
}

import std.collection.*
import std.regex.*
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        // Split on a space that follows '.' or '?', but avoid splitting after common abbreviations like "Mr."
        let pattern = "(?<!\\w\\.\\w.)(?<![A-Z][a-z]\\.)(?<=\\.|\\?)\\s"
        let regex = Regex(pattern)
        // Assume split returns Array<String>; convert to ArrayList<String>
        let parts: Array<String> = regex.split(sentences_string)
        var result = ArrayList<String>([])
        for (i in 0..parts.size) {
            let p: String = parts[i]
            if (p != "") {
                result.add(p, at: result.size)
            }
        }
        result
    }

    public func count_words(sentence: String): Int64 {
        // Count ASCII words separated by spaces; ignore punctuation and digits
        let runes = sentence.toRuneArray()
        var inWord: Bool = false
        var count: Int64 = 0

        for (i in 0..runes.size) {
            let ch: Rune = runes[i]
            // ASCII letter check
            let isLetter: Bool =
                (ch >= r'A' && ch <= r'Z') || (ch >= r'a' && ch <= r'z')

            if (isLetter) {
                inWord = true
            } else {
                // Any non-letter acts as a delimiter (spaces, punctuation, digits, etc.)
                if (inWord) {
                    count = count + 1
                    inWord = false
                }
            }
        }
        if (inWord) {
            count = count + 1
        }
        count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = this.split_sentences(sentences_string)
        var max_count: Int64 = 0
        for (i in 0..sentences.size) {
            let c = this.count_words(sentences[i])
            if (c > max_count) {
                max_count = c
            }
        }
        max_count
    }
}

import std.collection.*

class SQLGenerator {

    /*
    This class generates SQL statements for common operations on a table, such as SELECT, INSERT, UPDATE, and DELETE.
    */

    let table_name: String

    public init(table_name: String) {
        /*
        Initialize the table name.
        :param table_name: String
        */
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        /*
        Generates a SELECT SQL statement based on the specified fields and conditions.
        :param fields: Option<ArrayList<String>>, optional. Default is None. The list of fields to be queried.
        :param condition: Option<String>, optional. Default is None. The condition expression for the query.
        :return: String. The generated SQL statement.
        >>> sql = SQLGenerator("table1")
        >>> sql.select(fields: ArrayList<String>(["field1", "field2"]), condition: "filed3 = value1")
        'SELECT field1, field2 FROM table1 WHERE filed3 = value1;'
        */
        var fields_sql: String = "*"
        match (fields) {
            case Some<ArrayList<String>>(fs) => {
                if (fs.size > 0) {
                    var tmp: String = ""
                    for (i in 0..fs.size) {
                        if (i > 0) { tmp = tmp + ", " }
                        tmp = tmp + fs[i]
                    }
                    fields_sql = tmp
                } else {
                    fields_sql = ""  // Explicit empty list results in empty fields segment
                }
            }
            case _ => {
                fields_sql = "*"
            }
        }

        var sql: String = "SELECT " + fields_sql + " FROM " + this.table_name
        match (condition) {
            case Some<String>(cond) => { sql = sql + " WHERE " + cond }
            case _ => { /* no condition */ }
        }
        return sql + ";"
    }

    public func insert(data: HashMap<String, String>): String {
        /*
        Generates an INSERT SQL statement based on the given data.
        :param data: HashMap<String, String>. The data to be inserted, in dictionary form where keys are field names and values are field values.
        :return: String. The generated SQL statement.
        >>> sql.insert(HashMap<String, String>([('key1', 'value1'), ('key2', 'value2')]))
        "INSERT INTO table1 (key1, key2) VALUES ('value1', 'value2');"
        */
        let keys: ArrayList<String> = data.keys()
        var fields: String = ""
        var values: String = ""
        for (i in 0..keys.size) {
            let k = keys[i]
            let v = data[k]
            if (i > 0) {
                fields = fields + ", "
                values = values + ", "
            }
            fields = fields + k
            values = values + "'" + v + "'"
        }
        let sql: String = "INSERT INTO " + this.table_name + " (" + fields + ") VALUES (" + values + ");"
        return sql
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        /*
        Generates an UPDATE SQL statement based on the given data and condition.
        :param data: HashMap<String, String>. The data to be updated, in dictionary form where keys are field names and values are new field values.
        :param condition: String. The condition expression for the update.
        :return: String. The generated SQL statement.
        >>> sql.update(HashMap<String, String>([('field1', 'new_value1'), ('field2', 'new_value2')]), "field3 = value1")
        "UPDATE table1 SET field1 = 'new_value1', field2 = 'new_value2' WHERE field3 = value1;"
        */
        let keys: ArrayList<String> = data.keys()
        var set_clause: String = ""
        for (i in 0..keys.size) {
            let k = keys[i]
            let v = data[k]
            if (i > 0) {
                set_clause = set_clause + ", "
            }
            set_clause = set_clause + k + " = '" + v + "'"
        }
        let sql: String = "UPDATE " + this.table_name + " SET " + set_clause + " WHERE " + condition + ";"
        return sql
    }

    public func delete(condition: String): String {
        /*
        Generates a DELETE SQL statement based on the given condition.
        :param condition: String. The condition expression for the delete.
        :return: String. The generated SQL statement.
        >>> sql.delete("field1 = value1")
        'DELETE FROM table1 WHERE field1 = value1;'
        */
        return "DELETE FROM " + this.table_name + " WHERE " + condition + ";"
    }

    public func select_female_under_age(age: Int64): String {
        /*
        Generates a SQL statement to select females under a specified age.
        :param age: Int64. The specified age.
        :return: String. The generated SQL statement.
        >>> sql.select_female_under_age(30)
        "SELECT * FROM table1 WHERE age < 30 AND gender = 'female';"
        */
        let cond: String = "age < ${age} AND gender = 'female'"
        return this.select(condition: Some<String>(cond))
    }

    public func select_by_age_range(min_age: Int64, max_age: Int64): String {
        /*
        Generates a SQL statement to select records within a specified age range.
        :param min_age: Int64. The minimum age.
        :param max_age: Int64. The maximum age.
        :return: String. The generated SQL statement.
        >>> sql.select_by_age_range(20, 30)
        'SELECT * FROM table1 WHERE age BETWEEN 20 AND 30;'
        */
        let cond: String = "age BETWEEN ${min_age} AND ${max_age}"
        return this.select(condition: Some<String>(cond))
    }
}

import std.collection.*

class SQLQueryBuilder {

    /*
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    */

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(["*"]), where_condition!: Option<HashMap<String, String>> = None): String {
        /*
        Generate the SELECT SQL statement from the given parameters.
        :param table: String, the query table in database.
        :param columns: ArrayList of String, ["col1", "col2"].
        :param where_condition: Option<HashMap<String, String>>, {key1: value1, key2: value2 ...}. The query condition.
        :return query: String, the SQL query statement.
        >>> SQLQueryBuilder.select("table1", columns: ArrayList<String>(["col1","col2"]), where_condition: HashMap<String,String>([("age", "15")]))
        "SELECT col1, col2 FROM table1 WHERE age='15'"
        */
        var cols_str: String = ""
        for (i in 0..columns.size) {
            cols_str = "${cols_str}${columns[i]}"
            if (i < columns.size - 1) {
                cols_str = "${cols_str}, "
            }
        }

        var query: String = "SELECT ${cols_str} FROM ${table}"

        let where_map: HashMap<String, String> = where_condition ?? HashMap<String, String>([])
        if (where_map.size > 0) {
            let where_str = SQLQueryBuilder.build_where_clause(where_map)
            query = "${query} WHERE ${where_str}"
        }

        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        /*
        Generate the INSERT SQL statement from the given parameters.
        :param table: String, the table to be inserted in database.
        :param data: HashMap<String, String>, the key and value in SQL insert statement
        :return query: String, the SQL insert statement.
        >>> SQLQueryBuilder.insert("table1", HashMap<String,String>([("name", "Test"), ("age", "14")]))
        "INSERT INTO table1 (name, age) VALUES ('Test', '14')"
        */
        let keys_arr = data.keys()
        var keys_str: String = ""
        var vals_str: String = ""

        for (i in 0..keys_arr.size) {
            let k = keys_arr[i]
            let v = data[k]
            keys_str = "${keys_str}${k}"
            vals_str = "${vals_str}'${v}'"
            if (i < keys_arr.size - 1) {
                keys_str = "${keys_str}, "
                vals_str = "${vals_str}, "
            }
        }

        let query: String = "INSERT INTO ${table} (${keys_str}) VALUES (${vals_str})"
        return query
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        /*
        Generate the DELETE SQL statement from the given parameters.
        :param table: String, the table that will be executed with DELETE operation in database
        :param where_condition: Option<HashMap<String, String>>, {key1: value1, key2: value2 ...}. The query condition.
        :return query: String, the SQL delete statement.
        >>> SQLQueryBuilder.delete("table1", where_condition: HashMap<String,String>([("name", "Test"), ("age", "14")]))
        "DELETE FROM table1 WHERE name='Test' AND age='14'"
        */
        var query: String = "DELETE FROM ${table}"

        let where_map: HashMap<String, String> = where_condition ?? HashMap<String, String>([])
        if (where_map.size > 0) {
            let where_str = SQLQueryBuilder.build_where_clause(where_map)
            query = "${query} WHERE ${where_str}"
        }

        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        /*
        Generate the UPDATE SQL statement from the given parameters.
        :param table: String, the table that will be executed with UPDATE operation in database
        :param data: HashMap<String, String>, the key and value in SQL update statement
        :param where_condition: Option<HashMap<String, String>>, {key1: value1, key2: value2 ...}. The query condition.
        :return query: String, the SQL update statement.
        >>> SQLQueryBuilder.update("table1", HashMap<String,String>([("name", "Test2"), ("age", "15")]), where_condition: HashMap<String,String>([("name", "Test")]))
        "UPDATE table1 SET name='Test2', age='15' WHERE name='Test'"
        */
        let keys_arr = data.keys()
        var set_str: String = ""
        for (i in 0..keys_arr.size) {
            let k = keys_arr[i]
            let v = data[k]
            set_str = "${set_str}${k}='${v}'"
            if (i < keys_arr.size - 1) {
                set_str = "${set_str}, "
            }
        }

        var query: String = "UPDATE ${table} SET ${set_str}"

        let where_map: HashMap<String, String> = where_condition ?? HashMap<String, String>([])
        if (where_map.size > 0) {
            let where_str = SQLQueryBuilder.build_where_clause(where_map)
            query = "${query} WHERE ${where_str}"
        }

        return query
    }

    private static func build_where_clause(map: HashMap<String, String>): String {
        let keys_arr = map.keys()
        var where_str: String = ""
        for (i in 0..keys_arr.size) {
            let k = keys_arr[i]
            let v = map[k]
            where_str = "${where_str}${k}='${v}'"
            if (i < keys_arr.size - 1) {
                where_str = "${where_str} AND "
            }
        }
        return where_str
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.collection.HashSet
import std.math.sqrt
import std.sort.sort

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        // Sort in place
        sort(data)
        let n: Int64 = data.size as Int64
        if (n % 2 == 1) {
            return (data[n / 2]) as Float64
        } else {
            let a: Float64 = (data[(n / 2) - 1]) as Float64
            let b: Float64 = (data[n / 2]) as Float64
            return (a + b) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>([])
        var max_count: Int64 = 0
        // Count frequencies and track max
        for (i in 0..data.size) {
            let v = data[i]
            let cnt_opt = counts.get(v)
            let prev: Int64 = match (cnt_opt) {
                case Some<Int64>(c) => c
                case _ => 0
            }
            let now = prev + 1
            counts.add(v, now)
            if (now > max_count) {
                max_count = now
            }
        }
        // Collect all values with frequency == max_count (unique, order of first occurrence)
        var result = ArrayList<Int64>([])
        let seen = HashSet<Int64>([])
        for (i in 0..data.size) {
            let v = data[i]
            let cnt_opt = counts.get(v)
            let cnt: Int64 = match (cnt_opt) {
                case Some<Int64>(c) => c
                case _ => 0
            }
            if (cnt == max_count && !seen.contains(v)) {
                result.add(v, at: result.size)
                seen.add(v)
            }
        }
        return result
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size == 0 || y.size == 0 || x.size != y.size) {
            return None<Float64>
        }
        let n: Float64 = (x.size as Float64)

        // Means
        var sum_x: Float64 = 0.0
        var sum_y: Float64 = 0.0
        for (i in 0..x.size) {
            sum_x = sum_x + (x[i] as Float64)
            sum_y = sum_y + (y[i] as Float64)
        }
        let mean_x: Float64 = sum_x / n
        let mean_y: Float64 = sum_y / n

        // Numerator and denominator parts
        var num: Float64 = 0.0
        var ssx: Float64 = 0.0
        var ssy: Float64 = 0.0
        for (i in 0..x.size) {
            let dx: Float64 = (x[i] as Float64) - mean_x
            let dy: Float64 = (y[i] as Float64) - mean_y
            num = num + (dx * dy)
            ssx = ssx + (dx * dx)
            ssy = ssy + (dy * dy)
        }
        let denom: Float64 = sqrt(ssx * ssy)
        if (denom == 0.0) {
            return None<Float64>
        }
        return Some<Float64>(num / denom)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>
        }
        var sum: Float64 = 0.0
        for (i in 0..data.size) {
            sum = sum + (data[i] as Float64)
        }
        return Some<Float64>(sum / (data.size as Float64))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        var matrix = ArrayList<ArrayList<Float64>>([])
        if (data.size == 0) {
            return matrix
        }
        let rows: Int64 = data.size as Int64
        let cols: Int64 = data[0].size as Int64

        for (i in 0..cols) {
            var row = ArrayList<Float64>([])
            for (j in 0..cols) {
                // Build column i and j
                var col1 = ArrayList<Int64>([])
                var col2 = ArrayList<Int64>([])
                for (r in 0..rows) {
                    col1.add(data[r][i], at: col1.size)
                    col2.add(data[r][j], at: col2.size)
                }
                let corr_opt = Statistics3.correlation(col1, col2)
                let corr_val: Float64 = corr_opt ?? 0.0
                row.add(corr_val, at: row.size)
            }
            matrix.add(row, at: matrix.size)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n: Int64 = data.size as Int64
        if (n < 2) {
            return None<Float64>
        }
        let mean_opt = Statistics3.mean(data)
        let m = mean_opt.getOrThrow()
        var ss: Float64 = 0.0
        for (i in 0..data.size) {
            let d: Float64 = (data[i] as Float64) - m
            ss = ss + (d * d)
        }
        let variance: Float64 = ss / ((n - 1) as Float64)
        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_opt = Statistics3.mean(data)
        match (mean_opt) {
            case None<Float64> => return None<ArrayList<Float64>>
            case _ => { }
        }
        let std_opt = Statistics3.standard_deviation(data)
        match (std_opt) {
            case None<Float64> => return None<ArrayList<Float64>>
            case Some<Float64>(sd) => {
                if (sd == 0.0) {
                    return None<ArrayList<Float64>>
                }
                let m = mean_opt.getOrThrow()
                var res = ArrayList<Float64>([])
                for (i in 0..data.size) {
                    let z: Float64 = ((data[i] as Float64) - m) / sd
                    res.add(z, at: res.size)
                }
                return Some<ArrayList<Float64>>(res)
            }
        }
    }
}

import std.collection.*

class Stock <: Equatable<Stock> {

    let name: String
    var price: Float64
    var quantity: Int64

    public init(name: String, price: Float64, quantity: Int64) {
        this.name = name
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Stock): Bool {
        return this.name != that.name || this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Stock): Bool {
        return this.name == that.name && this.price == that.price && this.quantity == that.quantity
    }
}

class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        var i: Int64 = 0
        while (i < this.portfolio.size) {
            var pf: Stock = this.portfolio[i]
            if (pf.name == stock.name) {
                pf.quantity = pf.quantity + stock.quantity
                this.portfolio[i] = pf
                return
            }
            i = i + 1
        }
        this.portfolio.add(stock, at: this.portfolio.size)
    }

    public func remove_stock(stock: Stock): Bool {
        var i: Int64 = 0
        while (i < this.portfolio.size) {
            var pf: Stock = this.portfolio[i]
            if (pf.name == stock.name && pf.quantity >= stock.quantity) {
                pf.quantity = pf.quantity - stock.quantity
                if (pf.quantity == 0) {
                    this.portfolio.remove(at: i)
                } else {
                    this.portfolio[i] = pf
                }
                return true
            }
            i = i + 1
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let cost: Float64 = stock.price * stock.quantity
        if (cost > this.cash_balance) {
            return false
        } else {
            this.add_stock(stock)
            this.cash_balance = this.cash_balance - cost
            return true
        }
    }

    public func sell_stock(stock: Stock): Bool {
        if (this.remove_stock(stock) == false) {
            return false
        }
        let revenue: Float64 = stock.price * stock.quantity
        this.cash_balance = this.cash_balance + revenue
        return true
    }

    public func calculate_portfolio_value(): Float64 {
        var total_value: Float64 = this.cash_balance
        var i: Int64 = 0
        while (i < this.portfolio.size) {
            let st: Stock = this.portfolio[i]
            total_value = total_value + st.price * st.quantity
            i = i + 1
        }
        return total_value
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        var summary: ArrayList<HashMap<String, Any>> = ArrayList<HashMap<String, Any>>()
        var i: Int64 = 0
        while (i < this.portfolio.size) {
            let st: Stock = this.portfolio[i]
            let value: Float64 = this.get_stock_value(st)
            let entry = HashMap<String, Any>([("name", st.name), ("value", value)])
            summary.add(entry, at: summary.size)
            i = i + 1
        }
        let portfolio_value: Float64 = this.calculate_portfolio_value()
        return (portfolio_value, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * stock.quantity
    }
}

import std.math.abs

class Thermostat {

    /*
    The class manages temperature control, including setting and retrieving the target temperature, adjusting the mode, and simulating temperature operation.
    */

    var current_temperature: Float64
    var target_temperature: Float64
    var mode: String

    public init(current_temperature: Float64, target_temperature: Float64, mode: String) {
        /*
        initialize instances of the Thermostat class, including the current temperature, target temperature, and operating mode.
        :param current_temperature: Float64
        :param target_temperature: Float64
        :param mode: String, the work mode
        */
        this.current_temperature = current_temperature
        this.target_temperature = target_temperature
        this.mode = mode
    }

    public func get_target_temperature(): Float64 {
        /*
        Get the target temperature of an instance of the Thermostat class.
        :return this.target_temperature: Float64
        >>> thermostat.get_target_temperature()
        37.5
        */
        return this.target_temperature
    }

    public func set_target_temperature(temperature: Float64): Unit {
        /*
        Set the target temperature
        :param temperature: Float64, the target temperature
        >>> thermostat.set_target_temperature(37.6)
        >>> thermostat.target_temperature
        37.6
        */
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        /*
        Get the current work mode
        :return mode: String, working mode. only ['heat', 'cool']
        */
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        /*
        Get the current work mode
        :param mode: String, working mode. only ['heat', 'cool']
        >>> thermostat.set_mode('cool')
        >>> thermostat.mode
        'cool'
        */
        if (mode == "heat" || mode == "cool") {
            this.mode = mode
            return true
        } else {
            return false
        }
    }

    public func auto_set_mode(): Unit {
        /*
        Automatically set the operating mode by comparing with the current temperature and target temperature. If the current temperature is lower than the target temperature, the operating mode is set to 'heat', otherwise it is set to 'cool'.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.auto_set_mode()
        >>> thermostat.mode
        'heat'
        */
        if (this.current_temperature < this.target_temperature) {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        /*
        Check if there is a conflict between the operating mode and the relationship between the current temperature and the target temperature.
        If there is a conflict, the operating mode will be adjusted automatically.
        :return: true if mode isn't conflict with the relationship between the current temperature and the target temperature, or false otherwise.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.auto_check_conflict()
        false
        >>> thermostat.mode
        'heat'
        */
        if (this.current_temperature > this.target_temperature) {
            if (this.mode == "cool") {
                return true
            } else {
                this.auto_set_mode()
                return false
            }
        } else {
            if (this.mode == "heat") {
                return true
            } else {
                this.auto_set_mode()
                return false
            }
        }
    }

    public func simulate_operation(): Int64 {
        /*
        simulate the operation of Thermostat. It will automatically start the auto_set_mode method to set the operating mode,
        and then automatically adjust the current temperature according to the operating mode until the target temperature is reached.
        :return time: Int64, the time it took to complete the simulation.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.simulate_operation()
        18
        */
        this.auto_set_mode()
        var use_time: Int64 = 0
        if (this.mode == "heat") {
            while (this.current_temperature < this.target_temperature) {
                this.current_temperature = this.current_temperature + 1.0
                use_time = use_time + 1
            }
        } else {
            while (this.current_temperature > this.target_temperature) {
                this.current_temperature = this.current_temperature - 1.0
                use_time = use_time + 1
            }
        }
        return use_time
    }
}

