import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    /*
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    */

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        /*
        Calculate the cos value of the x-degree angle
        :param x:Float64
        :return:Float64
        >>> tricalculator = TriCalculator()
        >>> tricalculator.cos(60.0)
        0.5
        */
        return round(this.taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        /*
        Calculate the factorial of a
        :param a: Int64
        :return: Decimal
        >>> tricalculator.factorial(5)
        Decimal(120)
        */
        var b: Decimal = Decimal(1)
        var i: Int64 = a
        while (i != 1) {
            b = b * Decimal(i)
            i = i - 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        /*
        Finding the n-order Taylor expansion value of cos (x/180 * pi)
        :param x: Float64
        :param n: Int64
        :return: Float64
        >>> tricalculator.taylor(60.0, 50)
        0.5000000000000001
        */
        var xr: Float64 = x / 180.0 * PI
        var sum: Float64 = 1.0
        var t: Float64 = 1.0
        for (k in 1..n:1) {
            t = -t * xr * xr / (2 * k) / (2 * k - 1)
            sum = sum + t
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
        /*
        Calculate the sin value of the x-degree angle
        :param x: Float64
        :return: Float64
        >>> tricalculator.sin(30.0)
        0.5
        */
        var xr: Float64 = x / 180.0 * PI
        var g: Float64 = 0.0
        var t: Float64 = xr
        var n: Int64 = 1
        while (abs(t) >= 1e-15) {
            g = g + t
            n = n + 1
            t = -t * xr * xr / (2 * n - 1) / (2 * n - 2)
        }
        return round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        /*
        Calculate the tan value of the x-degree angle
        If the cosine is very close to 0 (|cos(x)| <= 1e-6), return None
        :param x: Float64
        :return: Option<Float64>
        >>> tricalculator.tan(45.0)
        1.0
        */
        let c: Float64 = this.cos(x)
        if (abs(c) <= 0.000001) {
            return None<Float64>
        } else {
            let s: Float64 = this.sin(x)
            let result: Float64 = s / c
            return Some<Float64>(round(result, 10))
        }
    }
}

import std.collection.*
import std.random.Random
import std.convert.Parsable

class Parser {

    /*
    This class is used to parse the expression to get the answer
    params: expression, String
    >>> parser = Parser("4+3+6+6")
    >>> parser.parse()
    19
    */

    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {

    /*
    This ia a game of twenty-four points, which provides to generate four numbers and check whether player's expression is equal to 24.
    */

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        /*
        Generate random numbers between 1 and 9 for the cards.
        */
        this.nums = ArrayList<Int64>()
        let rng = Random()
        for (i in 0..4) {
            // Assume Random provides randint(low, high) inclusive
            let v = rng.randint(1, 9)
            this.nums.add(v, at: this.nums.size)
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        /*
        Get a list of four random numbers between 1 and 9 representing the player's cards.
        :return: ArrayList<Int64>, representing the player's cards
        >>> game = TwentyFourPointGame()
        >>> game.get_my_cards()
        */
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        /*
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: String, mathematical expression using the cards
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> game.nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.answer(ans)
        true
        */
        if (expression == "pass") {
            // Regenerate cards on pass; result for answer is false
            this.get_my_cards()
            return false
        }

        // Count occurrences of each card value
        let card_counts = HashMap<Int64, Int64>()
        for (i in 0..this.nums.size) {
            let n = this.nums[i]
            let copt = card_counts.get(n)
            match (copt) {
                case Some<Int64>(c) => card_counts.add(n, c + 1)
                case None<Int64> => card_counts.add(n, 1)
            }
        }

        // Count digits used in expression; reject any digit not present in cards
        let expr_counts = HashMap<Int64, Int64>()
        for (i in 0..expression.size) {
            let ch = Rune(expression[i])
            if (ch.isAsciiNumber()) {
                let d = Int64.parse(expression[i..i + 1])
                let present = card_counts.get(d)
                match (present) {
                    case Some<Int64>(_) => {
                        let eopt = expr_counts.get(d)
                        match (eopt) {
                            case Some<Int64>(e) => expr_counts.add(d, e + 1)
                            case None<Int64> => expr_counts.add(d, 1)
                        }
                    }
                    case None<Int64> => {
                        // Expression uses a digit not in cards
                        return false
                    }
                }
            }
        }

        // Verify expression uses exactly the given cards (counts must match)
        for (i in 0..this.nums.size) {
            let v = this.nums[i]
            let copt = card_counts.get(v)
            let eopt = expr_counts.get(v)
            match (copt) {
                case Some<Int64>(cc) => {
                    match (eopt) {
                        case Some<Int64>(ee) => {
                            if (ee != cc) {
                                return false
                            }
                        }
                        case None<Int64> => {
                            // Card value not used in expression
                            return false
                        }
                    }
                }
                case None<Int64> => {
                    // Should not happen
                    return false
                }
            }
        }

        // Evaluate the expression; must equal 24
        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        /*
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: String, mathematical expression
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.evaluate_expression(ans)
        true
        */
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch (e: Exception) {
            return false
        }
    }
}

import std.collection.*

class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let scheme_end: Int64 = this.url.indexOf("://")
        if (scheme_end != -1) {
            let scheme = this.url.substring(0, scheme_end)
            return Some<String>(scheme)
        } else {
            return None<String>
        }
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let scheme_end: Int64 = this.url.indexOf("://")
        if (scheme_end == -1) {
            return None<String>
        }
        let without_scheme = this.url.substring(scheme_end + 3)
        let host_end_in_rest: Int64 = without_scheme.indexOf("/")
        if (host_end_in_rest != -1) {
            let host = without_scheme.substring(0, host_end_in_rest)
            return Some<String>(host)
        } else {
            return Some<String>(without_scheme)
        }
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let scheme_end: Int64 = this.url.indexOf("://")
        if (scheme_end == -1) {
            return None<String>
        }
        let without_scheme = this.url.substring(scheme_end + 3)
        let host_end_in_rest: Int64 = without_scheme.indexOf("/")
        if (host_end_in_rest != -1) {
            let path = without_scheme.substring(host_end_in_rest)
            return Some<String>(path)
        } else {
            return None<String>
        }
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let query_start: Int64 = this.url.indexOf("?")
        if (query_start == -1) {
            return None<HashMap<String, String>>
        }

        let fragment_start: Int64 = this.url.indexOf("#")
        let query_string: String = if (fragment_start != -1 && fragment_start > query_start) {
            this.url.substring(query_start + 1, fragment_start)
        } else {
            this.url.substring(query_start + 1)
        }

        var params = HashMap<String, String>()
        if (query_string != "") {
            let pairs = query_string.split("&")
            for (i in 0..pairs.size) {
                let pair = pairs[i]
                let kv = pair.split("=")
                if (kv.size == 2) {
                    params.add(kv[0], kv[1])
                }
            }
        }

        return Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let fragment_start: Int64 = this.url.indexOf("#")
        if (fragment_start != -1) {
            let fragment = this.url.substring(fragment_start + 1)
            return Some<String>(fragment)
        } else {
            return None<String>
        }
    }
}

import std.collection.*

class UrlPath {

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        let s = UrlPath.fix_path(segment)
        if (s != "") {
            this.segments.add(s, at: this.segments.size)
        }
    }

    public func parse(path: String): Unit {
        if (path == "") { return }

        // Detect trailing slash to set with_end_tag
        let runes = path.toRuneArray()
        if (runes.size > 0 && runes[runes.size - 1] == r'/') {
            this.with_end_tag = true
        } else {
            this.with_end_tag = false
        }

        let fixed = UrlPath.fix_path(path)
        if (fixed == "") { return }

        let parts = fixed.split("/")  // Split on '/'
        for (i in 0..parts.size) {
            let seg = parts[i]
            if (seg != "") {
                this.segments.add(seg, at: this.segments.size)
            }
        }
    }

    public static func fix_path(path: String): String {
        if (path == "") { return "" }
        let parts = path.split("/")

        var out: String = ""
        for (i in 0..parts.size) {
            let p = parts[i]
            if (p == "") { continue }
            if (out == "") { out = p } else { out = out + "/" + p }
        }
        return out
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.sqrt
import std.math.log

class VectorUtil {

    /*
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    */

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let norm1 = VectorUtil.norm(vector_1)
        let norm2 = VectorUtil.norm(vector_2)

        if (norm1 == 0.0 || norm2 == 0.0) {
            return 0.0
        }

        let d = VectorUtil.dot(vector_1, vector_2)
        return d / (norm1 * norm2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let res = ArrayList<Float64>([])
        let norm1 = VectorUtil.norm(vector_1)

        for (i in 0..vectors_all.size) {
            let v = vectors_all[i]
            let normi = VectorUtil.norm(v)

            let sim = if (norm1 == 0.0 || normi == 0.0) {
                0.0
            } else {
                VectorUtil.dot(v, vector_1) / (norm1 * normi)
            }

            res.add(sim, at: res.size)
        }

        return res
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size == 0 || vector_list_2.size == 0) {
            // When either list is empty, return 0.0 similarity to avoid division by zero.
            return 0.0
        }

        let dim1 = vector_list_1[0].size
        let dim2 = vector_list_2[0].size
        let dim = if (dim1 < dim2) { dim1 } else { dim2 }

        var sum1 = ArrayList<Float64>([])
        var sum2 = ArrayList<Float64>([])
        for (j in 0..dim) {
            sum1.add(0.0, at: sum1.size)
            sum2.add(0.0, at: sum2.size)
        }

        for (i in 0..vector_list_1.size) {
            let v = vector_list_1[i]
            for (j in 0..dim) {
                sum1[j] = sum1[j] + v[j]
            }
        }

        for (i in 0..vector_list_2.size) {
            let v = vector_list_2[i]
            for (j in 0..dim) {
                sum2[j] = sum2[j] + v[j]
            }
        }

        let n1 = vector_list_1.size as Float64
        let n2 = vector_list_2.size as Float64
        for (j in 0..dim) {
            sum1[j] = sum1[j] / n1
            sum2[j] = sum2[j] / n2
        }

        return VectorUtil.similarity(sum1, sum2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>([])
        // Conservatively assume a common keys() method to iterate over HashMap keys.
        let keys = number_dict.keys()

        for (i in 0..keys.size) {
            let key = keys[i]
            let count = number_dict[key]
            let denom = count + 1.0
            let numer = (total_num as Float64) + 1.0
            let w = log(numer / denom)
            result.add(key, w)
        }

        return result
    }

    private static func dot(a: ArrayList<Float64>, b: ArrayList<Float64>): Float64 {
        let lenA = a.size
        let lenB = b.size
        let len = if (lenA < lenB) { lenA } else { lenB }
        var s: Float64 = 0.0
        for (i in 0..len) {
            s = s + a[i] * b[i]
        }
        return s
    }

    private static func norm(a: ArrayList<Float64>): Float64 {
        var s: Float64 = 0.0
        for (i in 0..a.size) {
            let v = a[i]
            s = s + v * v
        }
        return sqrt(s)
    }
}

